--
-- Name: copy_email_for_authenticated_user(); Type: FUNCTION; Schema: public; Owner: admin
--

CREATE FUNCTION public.copy_email_for_authenticated_user() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
            BEGIN
                IF NEW.user_id IS NOT NULL THEN
                    SELECT email INTO NEW.email FROM users_user WHERE id = NEW.user_id;
                END IF;
                RETURN NEW;
            END;
            $$;


ALTER FUNCTION public.copy_email_for_authenticated_user() OWNER TO admin;

